await Array.fromAsync(walk(".", { followSymlinks: true, canonicalize: true }));
// [
//   {
//     path: ".",
//     name: ".",
//     isFile: false,
//     isDirectory: true,
//     isSymlink: false
//   },
//   {
//     path: "script.ts",
//     name: "script.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false
//   },
//   {
//     path: "link",
//     name: "link",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: true
