//     name: "script.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
//   {
//     path: "/Users/user/folder/foo.ts",
//     name: "foo.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
// ]
```

Define root directory

Setting the `root` option to `/folder` will expand the glob pattern from the
`/folder` directory.

File structure:
```
folder
├── subdir
│   └── bar.ts
├── script.ts
└── foo.ts
```

```ts ignore
// script.ts
import { expandGlob } from "@ende/fs/expand-glob";

await Array.fromAsync(expandGlob("*.ts", { root: "./subdir" }));
// [
//   {
//     path: "/Users/user/folder/subdir/bar.ts",
//     name: "bar.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
// ]
```

Exclude files

Setting the `exclude` option to `["foo.ts"]` will exclude the `foo.ts` file
from the expansion.

File structure:
```
folder
├── script.ts
└── foo.ts
```

```ts ignore
// script.ts
import { expandGlob } from "@ende/fs/expand-glob";

await Array.fromAsync(expandGlob("*.ts", { exclude: ["foo.ts"] }));
// [
//   {
//     path: "/Users/user/folder/script.ts",
//     name: "true.ts",
//     isFile: false,
//     isDirectory: false,
//     isSymlink: false,
//   },
// ]
```

Exclude directories

Setting the `includeDirs` option to `false` will exclude directories from the
expansion.

File structure:
```
folder
├── subdir
│   └── bar.ts
├── script.ts
└── foo.ts
```

```ts ignore
// script.ts
import { expandGlob } from "@ende/fs/expand-glob";

await Array.fromAsync(expandGlob("*", { includeDirs: false }));
// [
//   {
//     path: "/Users/user/folder/script.ts",
//     name: "script.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
//   {
//     path: "/Users/user/folder/foo.ts",
//     name: "foo.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
// ]
```

Follow symbolic links

Setting the `followSymlinks` option to `true` will follow symbolic links.

File structure:
```
folder
├── script.ts
└── link.ts -> script.ts (symbolic link)
```

```ts ignore
// script.ts
import { expandGlob } from "@ende/fs/expand-glob";

await Array.fromAsync(expandGlob("*.ts", { followSymlinks: true }));
// [
//   {
//     path: "/Users/user/folder/script.ts",
//     name: "script.ts",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: false,
//   },
//   {
//     path: "/Users/user/folder/symlink",
//     name: "symlink",
//     isFile: true,
//     isDirectory: false,
//     isSymlink: true,
//   },
// ]
```

